   129	// dropped, not allowed to hide a good common one.
   130	const parse = (section) =>
   131	  Object.fromEntries(
   132	    Object.entries(section)
   133	      .filter(([id, v]) => kb.isKeybindingActionId(id) && expand(id, v) !== undefined)
   134	      .map(([id, v]) => [id, expand(id, v)]),
   135	  );
   136	const commonParsed = parse(common);
   137	const effective = { ...commonParsed, ...parse(linux) };
   138	for (;;) {
   139	  const withdrawn = kb
   140	    .findKeybindingConflicts('linux', effective)
   141	    .flatMap((c) => c.actionIds)
   142	    .filter((id) => id in written);
   143	  // Only generated keys are ever withdrawn. A conflict with none left in it
   144	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
   145	  // withdrawal brought back -- is Orca's to report.
   146	  if (withdrawn.length === 0) break;
   147	  for (const id of new Set(withdrawn)) {
   148	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
   149	    delete written[id];
   150	    delete linux[id];
   151	    if (id in commonParsed) effective[id] = commonParsed[id];
   152	    else delete effective[id];
   153	  }
   154	}
   155	
   156	doc.version = 1;
   157	doc.platforms = {
   158	  ...platforms,
   159	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   160	  linux,
   161	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   162	};
   163	writeJson(dest, doc);
   164	// Every key this table claims, written or withdrawn, at its generated value;
   165	// the UI's keep the value last written. Either way a later UI value reads as
   166	// changed, the UI's, rather than as never owned and free to overwrite.
   167	writeJson(sidecar, {
   168	  linux: {
   169	    ...owned,
   170	    ...Object.fromEntries([...theirs].filter((id) => id in prev).map((id) => [id, prev[id]])),
   171	    ...written,
   172	  },
   173	});
